{
  "name": "llm-usage-extraction",
  "version": "0.4.0",
  "description": "Read token usage from the local session logs of Claude Code, Claude Cowork, Codex, Cursor and OpenCode",
  "type": "module",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/HansKristoffer/llm-usage-extraction.git"
  },
  "homepage": "https://github.com/HansKristoffer/llm-usage-extraction#readme",
  "bugs": {
    "url": "https://github.com/HansKristoffer/llm-usage-extraction/issues"
  },
  "author": "Kristoffer Hansen",
  "keywords": [
    "claude-code",
    "codex",
    "cursor",
    "opencode",
    "token-usage",
    "bun"
  ],
  "engines": {
    "bun": ">=1.2.0"
  },
  "files": [
    "src"
  ],
  "exports": {
    ".": "./src/index.ts"
  },
  "scripts": {
    "test": "bun test",
    "typecheck": "tsc --noEmit",
    "lint": "bun run typecheck && biome ci .",
    "format": "biome check --write .",
    "verify:package": "node scripts/verify-package.mjs"
  },
  "devDependencies": {
    "@biomejs/biome": "^2.4.16",
    "@types/bun": "latest",
    "typescript": "^5.9.0"
  },
  "packageManager": "bun@1.4.4"
}
